JinxOracleWrapper jinx_lookup_oracle_wrapper(const char *name) {
    for (size_t i = 0; oracle_dispatch_table[i].name != NULL; i++) {
        if (strcmp(oracle_dispatch_table[i].name, name) == 0) {
            return oracle_dispatch_table[i].wrapper;
        }
    }

    return NULL;
}

JinxValue jinx_call_builtin_through_oracle(
    const char *name,
    const JinxValue *args,
    size_t argc
) {
    if (args != NULL && argc >= 1 && jinx_oracle_name_is_zend_container_builtin(name)) {
        return jinx_oracle_zend_array_dispatch_builtin(name, args, argc);
    }

    if (argc >= 1 && args != NULL && jinx_oracle_name_is_zend_array_builtin(name) &&
        jinx_oracle_value_is_zend_array(args[0])) {
        return jinx_oracle_zend_array_dispatch_builtin(name, args, argc);
    }

    JinxOracleWrapper wrapper = jinx_lookup_oracle_wrapper(name);

    if (wrapper == NULL) {
        return jinx_value_null();
    }

    JinxOracleAsmContext ctx;
    jinx_ora_context_init(&ctx, (JinxValue *) args, (uint32_t) argc);

    JinxValue result = wrapper(&ctx);

    if (ctx.fault != NULL) {
        return jinx_value_null();
    }

    return result;
}
